vector<int> topKFrequent(vector<int>& a, int k) {
    unordered_map<int,int> c; for (int x : a) c[x]++;
    vector<pair<int,int>> v; for (auto& [x, n] : c) v.push_back({-n, x});
    partial_sort(v.begin(), v.begin() + k, v.end());
    vector<int> out; for (int i = 0; i < k; i++) out.push_back(v[i].second); return out;
}
